const payload = $json.body ?? $json;

function firstDefined(...values) {
  return values.find((value) => value !== undefined && value !== null);
}

function normalizeText(message) {
  return firstDefined(
    message?.conversation,
    message?.extendedTextMessage?.text,
    message?.imageMessage?.caption,
    message?.videoMessage?.caption,
    message?.documentMessage?.caption,
    ''
  );
}

function extractAudio(message) {
  return {
    url: firstDefined(message?.audioMessage?.url, message?.pttMessage?.url, null),
    base64: firstDefined(message?.audioMessage?.base64, message?.pttMessage?.base64, null),
    mimeType: firstDefined(message?.audioMessage?.mimetype, message?.pttMessage?.mimetype, 'audio/ogg')
  };
}

function detectProductIntent(value) {
  return /(product|products|price|cost|stock|available|availability|catalog|item|buy|purchase|details)/i.test(value || '');
}

function detectOrderIntent(value) {
  return /(order status|status of (my )?order|where is my order|track(ing)?( my)? order|shipment|shipping status|delivery status|invoice|bill|order #|order number)/i.test(value || '');
}

function detectPaymentIntent(value) {
  return /(payment option|payment options|payment method|payment methods|how can i pay|how to pay|upi|card|credit card|debit card|cash on delivery|cod|bank transfer|net banking)/i.test(value || '');
}

function detectStoreInfoIntent(value) {
  return /(where is your store|store location|shop location|branch|open today|close today|opening hours|closing time|contact number|phone number|email address|store hours|working hours|address|location)/i.test(value || '');
}

function extractOrderLookupText(value) {
  const orderMatch = value?.match(/#?\d{3,}/);
  return orderMatch ? orderMatch[0].replace('#', '') : value;
}

const event = firstDefined(payload?.event, payload?.type, payload?.data?.event, 'unknown');
const data = firstDefined(payload?.data, payload);
const key = firstDefined(data?.key, data?.message?.key, data?.messages?.[0]?.key, {});
const message = firstDefined(data?.message, data?.messages?.[0]?.message, {});
const remoteJid = firstDefined(key?.remoteJid, data?.remoteJid, '');
const fromMe = Boolean(firstDefined(key?.fromMe, data?.fromMe, false));
const isGroup = remoteJid.endsWith('@g.us');
const isStatus = remoteJid === 'status@broadcast';
const senderNumber = remoteJid.replace(/@.+$/, '').replace(/\D/g, '');
const text = normalizeText(message).trim();
const audio = extractAudio(message);
const isAudio = Boolean(audio.url || audio.base64);
const hasImage = Boolean(message?.imageMessage);
const hasDocument = Boolean(message?.documentMessage);

if (fromMe || isGroup || isStatus) {
  return { json: { action: 'skipped', reason: 'self-group-or-status', route: 'skip', event, remoteJid } };
}

if (!senderNumber) {
  return { json: { action: 'skipped', reason: 'missing-sender-number', route: 'skip', event, remoteJid } };
}

if (!text && !isAudio) {
  return { json: { action: 'skipped', reason: 'no-text-or-audio', route: 'skip', event, remoteJid } };
}

let promptText = text;
let transcription = null;

if (isAudio) {
  const openAiKey = process.env.OPENAI_API_KEY;
  if (!openAiKey) {
    throw new Error('OPENAI_API_KEY is missing in the n8n environment');
  }

  let audioBuffer;
  if (audio.base64) {
    const normalizedBase64 = audio.base64.includes(',') ? audio.base64.split(',').pop() : audio.base64;
    audioBuffer = Buffer.from(normalizedBase64, 'base64');
  } else {
    const audioResponse = await fetch(audio.url);
    if (!audioResponse.ok) {
      throw new Error(`Failed to download audio: ${audioResponse.status} ${audioResponse.statusText}`);
    }
    audioBuffer = Buffer.from(await audioResponse.arrayBuffer());
  }

  const formData = new FormData();
  const extension = audio.mimeType.includes('mpeg') ? 'mp3' : audio.mimeType.includes('mp4') ? 'm4a' : 'ogg';
  formData.append('file', new Blob([audioBuffer], { type: audio.mimeType }), `voice-note.${extension}`);
  formData.append('model', 'whisper-1');

  const transcriptionResponse = await fetch('https://api.openai.com/v1/audio/transcriptions', {
    method: 'POST',
    headers: { Authorization: `Bearer ${openAiKey}` },
    body: formData
  });

  if (!transcriptionResponse.ok) {
    const errorText = await transcriptionResponse.text();
    throw new Error(`Whisper transcription failed: ${transcriptionResponse.status} ${errorText}`);
  }

  const transcriptionPayload = await transcriptionResponse.json();
  transcription = transcriptionPayload.text?.trim() ?? '';
  promptText = transcription;
}

if (!promptText) {
  return { json: { action: 'skipped', reason: 'empty-prompt-after-normalization', route: 'skip', event, remoteJid } };
}

const accountOrRefundSignals = /(refund|return|exchange|my account|my address|owner|manager)/i;
const visualSignals = /(match|same|similar|check|identify|compare|from (this|the) (photo|image|pic)|see (this|the) (photo|image|pic))/i;
const requiresHuman = hasImage || hasDocument || visualSignals.test(promptText) || accountOrRefundSignals.test(promptText);
const productIntent = !requiresHuman && detectProductIntent(promptText);
const orderIntent = !requiresHuman && detectOrderIntent(promptText);
const paymentIntent = !requiresHuman && !orderIntent && detectPaymentIntent(promptText);
const storeInfoIntent = !requiresHuman && !orderIntent && !paymentIntent && detectStoreInfoIntent(promptText);
const handoffReason = hasImage
  ? 'image-review'
  : hasDocument
    ? 'document-review'
    : visualSignals.test(promptText)
      ? 'visual-product-match'
      : accountOrRefundSignals.test(promptText)
        ? 'account-or-refund-details'
        : null;

let route = 'general';
if (requiresHuman) {
  route = 'human';
} else if (orderIntent) {
  route = 'order';
} else if (paymentIntent) {
  route = 'payment';
} else if (storeInfoIntent) {
  route = 'store';
} else if (productIntent) {
  route = 'product';
}

return {
  json: {
    action: 'routed',
    event,
    remoteJid,
    senderNumber,
    promptText,
    originalText: text,
    transcription,
    route,
    productIntent,
    orderIntent,
    paymentIntent,
    storeInfoIntent,
    orderLookupText: extractOrderLookupText(promptText),
    requiresHuman,
    handoffReason,
    hasImage,
    hasDocument,
    isAudio
  }
};

function ensureEnv(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(`${name} is missing in the n8n environment`);
  }
  return value;
}

async function notifyHuman(payload) {
  const handoffWebhookUrl = process.env.HUMAN_HANDOFF_WEBHOOK_URL;
  if (!handoffWebhookUrl) {
    return null;
  }

  const response = await fetch(handoffWebhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  const responseText = await response.text();
  if (!response.ok) {
    throw new Error(`Human handoff webhook failed: ${response.status} ${responseText}`);
  }

  return responseText;
}

const evolutionApiKey = ensureEnv('EVOLUTION_API_KEY');
const evolutionInstance = ensureEnv('EVOLUTION_INSTANCE');
const evolutionServerUrl = ensureEnv('EVOLUTION_SERVER_URL');

const replyMap = {
  'image-review': 'Thanks for sharing that. I am forwarding this to a team member so they can review the image and help you properly.',
  'document-review': 'I am forwarding this to a team member so they can review the document and help you properly.',
  'visual-product-match': 'I cannot reliably verify product matches from a photo here, so I am forwarding this to a team member.',
  'account-or-refund-details': 'I am forwarding this to a team member so they can confirm the exact account or refund details for you.'
};

const replyText = replyMap[$json.handoffReason] || 'I am forwarding this to a team member who can help you with this request.';
const handoffPayload = {
  source: 'whatsapp-ai-auto-reply',
  senderNumber: $json.senderNumber,
  remoteJid: $json.remoteJid,
  promptText: $json.promptText,
  originalText: $json.originalText,
  transcription: $json.transcription,
  handoffReason: $json.handoffReason,
  event: $json.event,
  occurredAt: new Date().toISOString()
};

const handoffResponse = await notifyHuman(handoffPayload);

const sendResponse = await fetch(`${evolutionServerUrl}/message/sendText/${evolutionInstance}`, {
  method: 'POST',
  headers: { apikey: evolutionApiKey, 'Content-Type': 'application/json' },
  body: JSON.stringify({ number: $json.senderNumber, text: replyText })
});

const sendPayload = await sendResponse.json().catch(() => ({}));
if (!sendResponse.ok) {
  throw new Error(`Evolution sendText failed: ${sendResponse.status} ${JSON.stringify(sendPayload)}`);
}

return {
  json: {
    action: 'human-handoff',
    senderNumber: $json.senderNumber,
    handoffReason: $json.handoffReason,
    promptText: $json.promptText,
    replyText,
    handoffPayload,
    handoffResponse,
    evolutionResponse: sendPayload
  }
};

const storeInfoContext = [
  'Store address: Update this branch with your real showroom or pickup location before going live.',
  'Opening hours: Update this branch with your real business hours.',
  'Contact phone: Update this branch with your real support number.',
  'Support email: Update this branch with your real support email.'
].join('\n');

const systemPrompt = `You are a multilingual WhatsApp assistant.
Reply in the same language used by the customer.
Keep responses short, natural, and WhatsApp-friendly.
Do not use markdown.
Use only the store info context provided.
If exact branch-specific details are missing, ask the customer to contact the team.`;

const userPrompt = `Customer message:
${$json.promptText}\n\nStore info context:
${storeInfoContext}`;

return {
  json: {
    ...$json,
    openAiMessages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  }
};

