function stripHtml(value) {
  return value ? value.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() : '';
}

async function notifyHuman(payload) {
  const handoffWebhookUrl = process.env.HUMAN_HANDOFF_WEBHOOK_URL;
  if (!handoffWebhookUrl) {
    return null;
  }

  const response = await fetch(handoffWebhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  const responseText = await response.text();
  if (!response.ok) {
    throw new Error(`Human handoff webhook failed: ${response.status} ${responseText}`);
  }

  return responseText;
}

