if (!products.length) {
  const replyText = 'I could not find an exact product match in the catalog right now, so I am forwarding this to a team member for a manual check.';
  const handoffResponse = await notifyHuman({
    source: 'whatsapp-ai-auto-reply',
    senderNumber: original.senderNumber,
    remoteJid: original.remoteJid,
    promptText: original.promptText,
    originalText: original.originalText,
    transcription: original.transcription,
    handoffReason: 'no-product-match',
    event: original.event,
    occurredAt: new Date().toISOString()
  });

  return {
    json: {
      ...original,
      action: 'product-handoff',
      matchedProducts: [],
      handoffResponse,
      replyText,
      aiRequired: false
    }
  };
}

